export function svg(name, opts) {
  const o = opts || {};
  const g = GLYPHS[name] || GLYPHS.dot;
  const dim = o.cssSized ? "" : ' width="' + (o.size || DEFAULTS.size) + '" height="' + (o.size || DEFAULTS.size) + '"';
  const sw = o.cssSized ? "" : ' stroke-width="' + (o.stroke || DEFAULTS.stroke) + '"';
  return '<svg viewBox="0 0 ' + g.w + ' ' + g.h + '"' + dim + ' fill="none" stroke="currentColor"' + sw +
    ' stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + g.b + "</svg>";
}

export function icon(name, opts) {
  return '<span class="icon">' + svg(name, opts) + "</span>";
}
